//! ANOVA, multiple comparisons, GLM and Gage R&R, checked against Montgomery's
//! textbook examples, the AIAG measurement-systems data and independent
//! NumPy/SciPy computations (`common/data6.rs`, generated by `gen/stats_ref6.py`).

mod common;
use common::data6::*;
use openstats_stats::anova::*;
use openstats_stats::model::Data;
use openstats_stats::msa::*;
use openstats_stats::report::{Reportable, SessionReport};

fn close(got: f64, want: f64, rel: f64, what: &str) {
    let ok = if got == want {
        true
    } else if want == 0.0 {
        got.abs() <= rel
    } else {
        ((got - want) / want).abs() <= rel
    };
    assert!(ok, "{what}: got {got:e}, want {want:e}");
}

fn ow() -> OneWayAnova {
    one_way(OW_GROUPS, None, &OneWayOptions::default()).unwrap()
}

fn same_json(r: &SessionReport) {
    r.validate().unwrap();
    assert_eq!(SessionReport::from_json(&r.to_json()).unwrap().to_json(), r.to_json());
}

// ------------------------------------------------------------------ one-way

#[test]
fn one_way_matches_scipy_and_welch() {
    let a = ow();
    let r = OW_REF;
    close(a.ss_factor, r[0], 1e-12, "SSB");
    close(a.ss_error, r[1], 1e-12, "SSW");
    close(a.ss_total, r[2], 1e-12, "SST");
    close(a.f.unwrap(), r[3], 1e-11, "F");
    close(a.p_value.unwrap(), r[4], 1e-9, "p");
    close(a.s, r[5], 1e-12, "S");
    close(a.r2, r[6], 1e-12, "R2");
    close(a.r2_adj, r[7], 1e-11, "R2adj");
    close(a.r2_pred.unwrap(), r[8], 1e-11, "R2pred");
    let w = a.welch.as_ref().unwrap();
    close(w.f, r[9], 1e-11, "Welch F");
    assert_eq!(w.df1, r[10]);
    close(w.df2, r[11], 1e-11, "Welch df2");
    close(w.p_value, r[12], 1e-9, "Welch p");
    for (i, l) in a.levels.iter().enumerate() {
        close(l.mean, OW_MEANS[i], 1e-13, "mean");
        close(l.sd.unwrap(), OW_MEANS[4 + i], 1e-12, "sd");
        close(l.ci_pooled.lower, OW_CI_POOLED[i], 1e-11, "pooled CI lower");
        close(l.ci_pooled.upper, OW_CI_POOLED[4 + i], 1e-11, "pooled CI upper");
        let ci = l.ci_individual.unwrap();
        close(ci.lower, OW_CI_INDIV[i], 1e-11, "individual CI lower");
        close(ci.upper, OW_CI_INDIV[4 + i], 1e-11, "individual CI upper");
    }
    assert_eq!(a.interval_plot().series[1].x.len(), 4);
}

/// Montgomery, Example 3.1: plasma-etching rate at four RF power settings.
fn etching() -> OneWayAnova {
    let g: [&[f64]; 4] = [
        &[575.0, 542.0, 530.0, 539.0, 570.0],
        &[565.0, 593.0, 590.0, 579.0, 610.0],
        &[600.0, 651.0, 610.0, 637.0, 629.0],
        &[725.0, 700.0, 715.0, 685.0, 710.0],
    ];
    let labels: Vec<String> = ["160", "180", "200", "220"].map(String::from).to_vec();
    one_way(&g, Some(&labels), &OneWayOptions::default()).unwrap()
}

#[test]
fn montgomery_etching_example() {
    let a = etching();
    close(a.ss_factor, 66870.55, 1e-9, "SS treatments");
    close(a.ss_error, 5339.20, 1e-9, "SSE");
    close(a.ms_factor, 22290.18, 1e-6, "MS treatments");
    close(a.ms_error, 333.70, 1e-9, "MSE");
    assert!((a.f.unwrap() - 66.80).abs() < 5e-3 && a.p_value.unwrap() < 1e-8);
    // Fisher LSD = 24.49 (Example 3.6); the Tukey half-width is q·√(MSE/n) = 33.05
    // (Montgomery's rounded table value q = 4.05 gives 33.09).
    let f = a.fisher(0.05).unwrap();
    close(f.differences[0].interval.upper - f.differences[0].diff, 24.49, 5e-4, "LSD");
    let t = a.tukey(0.05).unwrap();
    let half = t.differences[0].interval.upper - t.differences[0].diff;
    assert!((half - 33.05).abs() < 0.02 && (half - 33.09).abs() < 0.06, "Tukey half-width {half}");
    // Every pair differs by more than the Tukey half-width (the closest, 180 − 160, by 36.2): four groups.
    let g: Vec<(&str, &str)> = t.grouping.iter().map(|r| (r.label.as_str(), r.letters.as_str())).collect();
    assert_eq!(g, vec![("220", "A"), ("200", "B"), ("180", "C"), ("160", "D")]);
}

#[test]
fn tukey_fisher_match_scipy() {
    let a = ow();
    let t = a.tukey(0.05).unwrap();
    let f = a.fisher(0.05).unwrap();
    assert_eq!(t.differences.len(), 6);
    for (n, (tk, ls)) in t.differences.iter().zip(&f.differences).enumerate() {
        // References are mean_i − mean_j for i < j; ours are level − reference = mean_j − mean_i.
        let (rt, rl) = (&TK_REF[4 * n..4 * n + 4], &LSD_REF[4 * n..4 * n + 4]);
        close(tk.diff, -rt[0], 1e-11, "Tukey diff");
        assert!((tk.p_adjusted - rt[1]).abs() < 1e-7, "Tukey p {} vs {}", tk.p_adjusted, rt[1]);
        assert!(
            (tk.interval.lower + rt[3]).abs() < 1e-6 && (tk.interval.upper + rt[2]).abs() < 1e-6,
            "Tukey CI pair {n}"
        );
        close(ls.diff, -rl[0], 1e-11, "LSD diff");
        assert!((ls.p_adjusted - rl[1]).abs() < 1e-11, "LSD p");
        assert!((ls.interval.lower + rl[3]).abs() < 1e-10 && (ls.interval.upper + rl[2]).abs() < 1e-10);
    }
}

#[test]
fn dunnett_matches_independent_integral() {
    let a = ow();
    let two = a.dunnett(0, Alternative::TwoSided, 0.05).unwrap();
    let gt = a.dunnett(0, Alternative::Greater, 0.05).unwrap();
    let lt = a.dunnett(0, Alternative::Less, 0.05).unwrap();
    assert!(
        (two.critical - DUN_CRIT[0]).abs() < 2e-5 && (gt.critical - DUN_CRIT[1]).abs() < 2e-5,
        "{} {}",
        two.critical,
        gt.critical
    );
    for i in 0..3 {
        let r = &DUN_REF[9 * i..9 * i + 9];
        let (d2, dg, dl) = (&two.differences[i], &gt.differences[i], &lt.differences[i]);
        close(d2.diff, r[0], 1e-11, "diff");
        close(d2.t, r[1], 1e-11, "t");
        assert!((d2.p_adjusted - r[2]).abs() < 2e-5, "two-sided p {} vs {}", d2.p_adjusted, r[2]);
        assert!((dg.p_adjusted - r[3]).abs() < 2e-5 && (dl.p_adjusted - r[4]).abs() < 2e-5);
        assert!((d2.interval.lower - r[5]).abs() < 1e-4 && (d2.interval.upper - r[6]).abs() < 1e-4);
        assert!((dg.interval.lower - r[7]).abs() < 1e-4 && dg.interval.upper.is_infinite());
        assert!((dl.interval.upper - r[8]).abs() < 1e-4 && dl.interval.lower.is_infinite());
    }
    assert_eq!(two.control, Some(0));
    assert!(a.dunnett(7, Alternative::TwoSided, 0.05).is_err());
}

#[test]
fn hsu_mcb_matches_reference() {
    let a = ow();
    for (best, reference) in [(Best::Largest, MCB_MAX_REF), (Best::Smallest, MCB_MIN_REF)] {
        let m = a.hsu_mcb(best, 0.05).unwrap();
        for (i, r) in m.rows.iter().enumerate() {
            let x = &reference[4 * i..4 * i + 4];
            assert!(
                (r.lower - x[0]).abs() < 1e-4 && (r.center - x[1]).abs() < 1e-11 && (r.upper - x[2]).abs() < 1e-4,
                "{best:?} level {i}: {r:?} vs {x:?}"
            );
            assert!((r.critical - x[3]).abs() < 2e-5);
        }
    }
    // Balanced: the unique "best" cannot be rejected, the worst level is rejected.
    let b = one_way(MCB_BAL_GROUPS, None, &OneWayOptions::default()).unwrap().hsu_mcb(Best::Largest, 0.05).unwrap();
    for (i, r) in b.rows.iter().enumerate() {
        let x = &MCB_BAL_REF[4 * i..4 * i + 4];
        assert!((r.lower - x[0]).abs() < 1e-4 && (r.upper - x[2]).abs() < 1e-4, "balanced level {i}");
    }
    assert!(b.rows[3].possibly_best && !b.rows[0].possibly_best);
}

// ---------------------------------------------------------------------- GLM

fn glm1() -> Data {
    Data::new()
        .with_factor("A", GL1_A)
        .unwrap()
        .with_factor("B", GL1_B)
        .unwrap()
        .with_numeric("x", GL1_X.to_vec())
        .unwrap()
        .with_numeric("y", GL1_Y.to_vec())
        .unwrap()
}

#[test]
fn glm_unbalanced_with_covariate() {
    let g = glm("y ~ A + B + x + A*B", &glm1(), &GlmOptions::default()).unwrap();
    assert_eq!(g.sequential.len(), 4);
    for (i, s) in g.sequential.iter().enumerate() {
        close(s.seq_ss, GL1_SEQ[i], 1e-9, &format!("Type I SS of {}", s.source));
    }
    let terms: Vec<&openstats_stats::regression::AnovaRow> =
        g.fit.anova.iter().filter(|r| r.seq_ss.is_some()).collect();
    for (i, r) in terms.iter().enumerate() {
        close(r.adj_ss, GL1_ADJ[i], 1e-8, &format!("Type III SS of {}", r.source));
    }
    close(g.fit.sse, GL1_FIT[0], 1e-9, "SSE");
    close(g.fit.sst, GL1_FIT[2], 1e-11, "SST");
    assert_eq!(g.fit.n_coef() as f64, GL1_FIT[1]);
    let a = &g.ls_means[0];
    let b = &g.ls_means[1];
    assert_eq!((a.term.as_str(), b.term.as_str()), ("A", "B"));
    for (r, w) in a.rows.iter().zip(GL1_LSM_A) {
        close(r.mean, *w, 1e-9, "LS mean of A");
    }
    for (r, w) in b.rows.iter().zip(GL1_LSM_B) {
        close(r.mean, *w, 1e-9, "LS mean of B");
        assert!(r.se > 0.0 && r.ci.lower < r.mean && r.mean < r.ci.upper);
    }
    // Type I and Type III differ for the unbalanced design (the first term is the same).
    assert!((g.sequential[1].seq_ss - terms[1].adj_ss).abs() > 1e-6);
}

#[test]
fn glm_three_factor_unbalanced() {
    let d = Data::new()
        .with_factor("A", GL2_A)
        .unwrap()
        .with_factor("B", GL2_B)
        .unwrap()
        .with_factor("C", GL2_C)
        .unwrap()
        .with_numeric("y", GL2_Y.to_vec())
        .unwrap();
    let g = glm("y ~ A|B|C", &d, &GlmOptions::default()).unwrap();
    assert_eq!(g.sequential.len(), 7);
    let terms: Vec<&openstats_stats::regression::AnovaRow> =
        g.fit.anova.iter().filter(|r| r.seq_ss.is_some()).collect();
    for i in 0..7 {
        close(g.sequential[i].seq_ss, GL2_SEQ[i], 1e-8, &format!("Type I SS of {}", g.sequential[i].source));
        close(terms[i].adj_ss, GL2_ADJ[i], 1e-7, &format!("Type III SS of {}", terms[i].source));
    }
    close(g.fit.sse, GL2_FIT[0], 1e-8, "SSE");
    assert_eq!(g.ls_means.len(), 7);
    assert_eq!(g.ls_means[3].rows.len(), 6); // A*B
}

/// Montgomery, Example 5.1: battery life by material type and temperature.
#[test]
fn montgomery_battery_two_way() {
    let cells: [(&str, &str, [f64; 4]); 9] = [
        ("1", "15", [130.0, 155.0, 74.0, 180.0]),
        ("1", "70", [34.0, 40.0, 80.0, 75.0]),
        ("1", "125", [20.0, 70.0, 82.0, 58.0]),
        ("2", "15", [150.0, 188.0, 159.0, 126.0]),
        ("2", "70", [136.0, 122.0, 106.0, 115.0]),
        ("2", "125", [25.0, 70.0, 58.0, 45.0]),
        ("3", "15", [138.0, 110.0, 168.0, 160.0]),
        ("3", "70", [174.0, 120.0, 150.0, 139.0]),
        ("3", "125", [96.0, 104.0, 82.0, 60.0]),
    ];
    let (mut m, mut t, mut y) = (vec![], vec![], vec![]);
    for (a, b, v) in cells {
        for x in v {
            m.push(a);
            t.push(b);
            y.push(x);
        }
    }
    let d = Data::new()
        .with_factor("Material", &m)
        .unwrap()
        .with_factor("Temp", &t)
        .unwrap()
        .with_numeric("Life", y)
        .unwrap();
    let g = glm("Life ~ Material*Temp", &d, &GlmOptions::default()).unwrap();
    let row = |name: &str| g.fit.anova.iter().find(|r| r.source == name).unwrap();
    close(row("Material").adj_ss, 10683.72, 1e-6, "Material SS");
    close(row("Temp").adj_ss, 39118.72, 1e-6, "Temperature SS");
    close(row("Material*Temp").adj_ss, 9613.78, 1e-6, "Interaction SS");
    close(g.fit.sse, 18230.75, 1e-6, "Error SS");
    close(g.fit.sst, 77646.97, 1e-6, "Total SS");
    // Published F values (Table 5.1): 7.91, 28.97, 3.56 with p = 0.0020, <0.0001, 0.0186.
    assert!((row("Material").f.unwrap() - 7.91).abs() < 0.01);
    assert!((row("Temp").f.unwrap() - 28.97).abs() < 0.01);
    assert!((row("Material*Temp").f.unwrap() - 3.56).abs() < 0.01);
    assert!((row("Material").p_value.unwrap() - 0.0020).abs() < 5e-5);
    assert!((row("Material*Temp").p_value.unwrap() - 0.0186).abs() < 5e-5);
    // Balanced: sequential = adjusted.
    for s in &g.sequential {
        close(s.seq_ss, row(&s.source).adj_ss, 1e-9, "balanced Type I = Type III");
    }
    let ip = g.interaction_chart("Temp", "Material").unwrap();
    assert_eq!(ip.series.len(), 3);
    // Montgomery's interaction-plot cell means (Figure 5.9): material 1 at 15°F = 134.75.
    assert!((ip.series[0].y[0] - 134.75).abs() < 1e-9);
    assert_eq!(g.main_effects_chart("Material").unwrap().series[0].y.len(), 3);
}

// --------------------------------------------------------------- Gage R&R

fn aiag() -> (Vec<f64>, Vec<String>, Vec<String>) {
    let a: [[f64; 10]; 3] = [
        [0.29, -0.56, 1.34, 0.47, -0.80, 0.02, 0.59, -0.31, 2.26, -1.36],
        [0.41, -0.68, 1.17, 0.50, -0.92, -0.11, 0.75, -0.20, 1.99, -1.25],
        [0.64, -0.58, 1.27, 0.64, -0.84, -0.21, 0.66, -0.17, 2.01, -1.31],
    ];
    let b: [[f64; 10]; 3] = [
        [0.08, -0.47, 1.19, 0.01, -0.56, -0.20, 0.47, -0.63, 1.80, -1.68],
        [0.25, -1.22, 0.94, 1.03, -1.20, 0.22, 0.55, 0.08, 2.12, -1.62],
        [0.07, -0.68, 1.34, 0.20, -1.28, 0.06, 0.83, -0.34, 2.19, -1.50],
    ];
    let c: [[f64; 10]; 3] = [
        [0.04, -1.38, 0.88, 0.14, -1.46, -0.29, 0.02, -0.46, 1.77, -1.49],
        [-0.11, -1.13, 1.09, 0.20, -1.07, -0.67, 0.01, -0.56, 1.45, -1.77],
        [-0.15, -0.96, 0.67, 0.11, -1.45, -0.49, 0.21, -0.49, 1.87, -2.16],
    ];
    let (mut y, mut part, mut op) = (vec![], vec![], vec![]);
    for (name, trials) in [("A", a), ("B", b), ("C", c)] {
        for t in trials {
            for (p, v) in t.iter().enumerate() {
                y.push(*v);
                part.push((p + 1).to_string());
                op.push(name.to_string());
            }
        }
    }
    (y, part, op)
}

fn aiag_study() -> CrossedStudy {
    let (y, p, o) = aiag();
    CrossedStudy::from_stacked(&y, &p, &o).unwrap()
}

fn expect_anova(res: &GageResult, reference: &[f64]) {
    // layout: ss[5], ms[4], F[3], P[3], keep, variance components [repeat, operator, op*part, part]
    let kept = reference[15] == 1.0;
    assert_eq!(!res.interaction_dropped, kept, "interaction decision");
    close(res.interaction_p.unwrap(), reference[14], 1e-8, "interaction p");
    let full = res.anova_with_interaction.as_ref().unwrap_or(&res.anova);
    for (i, k) in [0usize, 1, 2, 3, 4].iter().enumerate() {
        close(full[i].ss, reference[*k], 1e-11, "SS");
    }
    for r in &res.anova {
        match r.source.as_str() {
            "Part" => {
                close(r.f.unwrap(), reference[9], 1e-9, "F part");
                close(r.p.unwrap(), reference[12], 1e-8, "P part");
            }
            "Operator" => {
                close(r.f.unwrap(), reference[10], 1e-9, "F operator");
                close(r.p.unwrap(), reference[13], 1e-8, "P operator");
            }
            _ => {}
        }
    }
    close(res.component(Source::Repeatability).unwrap().var, reference[16], 1e-10, "repeatability");
    close(res.component(Source::Operator).unwrap().var, reference[17], 1e-9, "operator");
    close(res.component(Source::PartToPart).unwrap().var, reference[19], 1e-10, "part-to-part");
    close(res.component(Source::OperatorByPart).map_or(0.0, |r| r.var), reference[18], 1e-9, "operator*part");
}

#[test]
fn aiag_anova_method_and_minitab_published_values() {
    let s = aiag_study();
    let auto = s.anova(&GageOptions::default()).unwrap();
    expect_anova(&auto, GR_AIAG_AUTO);
    // Published ANOVA table of the AIAG gage study (Minitab documentation).
    let full = auto.anova_with_interaction.as_ref().unwrap();
    assert_eq!(full.iter().map(|r| r.df).collect::<Vec<_>>(), vec![9, 2, 18, 60, 89]);
    close(full[0].ss, 88.3619, 1e-6, "SS part");
    close(full[1].ss, 3.1673, 5e-5, "SS operator");
    close(full[2].ss, 0.3590, 1e-4, "SS interaction");
    close(full[3].ss, 2.7589, 5e-5, "SS repeatability");
    close(full[0].f.unwrap(), 492.291, 1e-5, "F part (with interaction)");
    close(full[1].f.unwrap(), 79.406, 1e-5, "F operator");
    close(full[2].f.unwrap(), 0.434, 1e-3, "F interaction");
    assert!((auto.interaction_p.unwrap() - 0.974).abs() < 5e-4 && auto.interaction_dropped);
    let red = &auto.anova;
    assert_eq!(red.iter().map(|r| r.df).collect::<Vec<_>>(), vec![9, 2, 78, 89]);
    close(red[0].f.unwrap(), 245.614, 1e-5, "F part (without)");
    close(red[1].f.unwrap(), 39.617, 1e-5, "F operator (without)");
    // Variance components: repeatability 0.03997, operator 0.05146, part-to-part 1.08645.
    let rep = auto.component(Source::Repeatability).unwrap();
    close(rep.var, 0.03997, 1e-4, "repeatability");
    close(auto.component(Source::Reproducibility).unwrap().var, 0.05146, 1e-4, "reproducibility");
    close(auto.component(Source::PartToPart).unwrap().var, 1.08645, 1e-5, "part-to-part");
    let grr = auto.component(Source::TotalGageRr).unwrap();
    let tot = auto.component(Source::TotalVariation).unwrap();
    close(grr.var, 0.09143, 1e-4, "total gage R&R");
    assert!((grr.pct_contribution - 7.76).abs() < 0.01 && (grr.pct_study_var - 27.86).abs() < 0.01);
    close(tot.var, tot.var, 0.0, "total");
    close(grr.study_var, 6.0 * grr.sd, 1e-13, "study var");
    assert_eq!(auto.ndc, Some(4));
    assert!(auto.component(Source::OperatorByPart).is_none() && auto.charts.len() == 6);
}

#[test]
fn interaction_override_and_tolerance() {
    let s = aiag_study();
    let keep = s.anova(&GageOptions { interaction: Interaction::Keep, ..GageOptions::default() }).unwrap();
    expect_anova(&keep, GR_AIAG_FULL);
    assert!(!keep.interaction_dropped && keep.anova_with_interaction.is_none());
    // Interaction variance estimate is negative here, so it is set to zero and reported.
    assert!(keep.negative_set_to_zero.contains(&Source::OperatorByPart));
    assert_eq!(keep.component(Source::OperatorByPart).unwrap().var, 0.0);
    let drop = s
        .anova(&GageOptions { interaction: Interaction::Drop, alpha_interaction: 0.01, ..GageOptions::default() })
        .unwrap();
    assert!(drop.interaction_dropped);
    // Tolerance and the 5.15 multiplier.
    let t = s
        .anova(&GageOptions {
            study_sigma: 5.15,
            tolerance: Some(Tolerance::Limits { lsl: -4.0, usl: 4.0 }),
            ..GageOptions::default()
        })
        .unwrap();
    let grr = t.component(Source::TotalGageRr).unwrap();
    close(grr.study_var, 5.15 * grr.sd, 1e-13, "5.15 SD");
    close(grr.pct_tolerance.unwrap(), 100.0 * 5.15 * grr.sd / 8.0, 1e-12, "%tolerance");
    assert_eq!(t.tolerance, Some(8.0));
    assert!(s.anova(&GageOptions { tolerance: Some(Tolerance::Width(-1.0)), ..GageOptions::default() }).is_err());
    assert!(s.anova(&GageOptions { study_sigma: 0.0, ..GageOptions::default() }).is_err());
}

#[test]
fn aiag_xbar_r_method() {
    let r = aiag_study().xbar_r(&GageOptions::default()).unwrap();
    let x = r.xbar_r.as_ref().unwrap();
    let want = GR_AIAG_XBR;
    close(x.r_bar, want[0], 1e-12, "R-bar");
    close(x.operator_range, want[1], 1e-12, "operator range");
    close(x.part_range, want[2], 1e-12, "part range");
    close(x.equipment_variation, want[3], 1e-8, "EV");
    close(x.appraiser_variation, want[4], 1e-8, "AV");
    close(r.component(Source::TotalGageRr).unwrap().sd, want[5], 1e-8, "GRR");
    close(x.part_variation, want[6], 1e-8, "PV");
    close(r.component(Source::TotalVariation).unwrap().sd, want[7], 1e-8, "TV");
    // AIAG Measurement Systems Analysis manual, average-and-range method:
    // EV = 0.2019, AV = 0.2297, GRR = 0.3058, %GRR = 26.68 %, ndc = 5 (K-factors rounded in print).
    assert!((x.equipment_variation - 0.2019).abs() < 3e-4);
    assert!((x.appraiser_variation - 0.2297).abs() < 3e-4);
    assert!((r.component(Source::TotalGageRr).unwrap().sd - 0.3058).abs() < 3e-4);
    assert!((r.component(Source::TotalGageRr).unwrap().pct_study_var - 26.68).abs() < 0.05);
    assert_eq!(r.ndc, Some(5));
    assert!(r.anova.is_empty() && r.component(Source::Operator).is_none());
}

fn stacked_from_cells(
    rows: &[&[f64]],
    a_levels: usize,
    b_levels: usize,
    a: &str,
    b: &str,
) -> (Vec<f64>, Vec<String>, Vec<String>) {
    // rows are (first factor, second factor) in row-major order; trials within a row.
    let (mut y, mut f1, mut f2) = (vec![], vec![], vec![]);
    for i in 0..a_levels {
        for j in 0..b_levels {
            for v in rows[i * b_levels + j] {
                y.push(*v);
                f1.push(format!("{a}{}", i + 1));
                f2.push(format!("{b}{}", j + 1));
            }
        }
    }
    (y, f1, f2)
}

#[test]
fn interaction_retained_and_nested() {
    let (y, part, op) = stacked_from_cells(GR2_Y, 6, 3, "P", "O");
    let s = CrossedStudy::from_stacked(&y, &part, &op).unwrap();
    let r = s.anova(&GageOptions::default()).unwrap();
    expect_anova(&r, GR2_AUTO);
    assert!(!r.interaction_dropped && r.interaction_p.unwrap() < 0.25);
    assert!(r.component(Source::OperatorByPart).is_some() && r.anova.len() == 5);
    // Nested design.
    let (y, op, part) = stacked_from_cells(GRN_Y, 3, 4, "O", "P");
    let n = NestedStudy::from_stacked(&y, &part, &op).unwrap().anova(&GageOptions::default()).unwrap();
    let w = GRN_REF;
    let ss = |i: usize| n.anova[i].ss;
    close(ss(0), w[0], 1e-10, "SS operator");
    close(ss(1), w[1], 1e-10, "SS part(operator)");
    close(ss(2), w[2], 1e-9, "SS error");
    close(ss(3), w[3], 1e-11, "SS total");
    close(n.anova[0].f.unwrap(), w[7], 1e-9, "F operator");
    close(n.anova[1].f.unwrap(), w[8], 1e-9, "F part(operator)");
    close(n.anova[0].p.unwrap(), w[9], 1e-8, "P operator");
    close(n.anova[1].p.unwrap(), w[10], 1e-8, "P part(operator)");
    close(n.component(Source::Repeatability).unwrap().var, w[11], 1e-10, "repeatability");
    close(n.component(Source::Reproducibility).unwrap().var, w[12], 1e-9, "reproducibility");
    close(n.component(Source::PartToPart).unwrap().var, w[13], 1e-10, "part-to-part");
    assert_eq!((n.parts, n.operators, n.replicates), (4, 3, 3));
    assert_eq!(n.charts.len(), 5);
}

#[test]
fn gage_study_validation() {
    let (y, part, op) = aiag();
    // Missing measurement, unbalanced cell, missing label, mismatched lengths.
    let mut bad = y.clone();
    bad[3] = f64::NAN;
    assert!(CrossedStudy::from_stacked(&bad, &part, &op).is_err());
    assert!(CrossedStudy::from_stacked(&y[1..], &part[1..], &op[..op.len() - 1]).is_err());
    assert!(CrossedStudy::from_stacked(&y[1..], &part[1..], &op[1..]).is_err());
    let mut p2 = part.clone();
    p2[0] = String::new();
    assert!(CrossedStudy::from_stacked(&y, &p2, &op).is_err());
    assert!(CrossedStudy::from_stacked(&y[..30], &part[..30], &op[..30]).is_err(), "one operator only");
    assert!(NestedStudy::from_stacked(&y[..30], &part[..30], &op[..30]).is_err());
    let one_rep: Vec<String> = (0..4).map(|i| (i % 2).to_string()).collect();
    assert!(
        CrossedStudy::from_stacked(&[1.0, 2.0, 3.0, 4.0], &one_rep, &["a", "a", "b", "b"].map(String::from)).is_err()
    );
}

// ----------------------------------------------------- reports and charts

#[test]
fn reports_render_and_round_trip() {
    let s = aiag_study();
    let a = s.anova(&GageOptions { tolerance: Some(Tolerance::Width(8.0)), ..GageOptions::default() }).unwrap();
    let r = a.to_report("Gage R&R");
    same_json(&r);
    let text = r.render_text();
    for key in [
        "Gage R&R Study - ANOVA Method",
        "Two-Way ANOVA Table Without Interaction",
        "Total Gage R&R",
        "Part-To-Part",
        "%Contribution (of VarComp)",
        "%Study Var (%SV)",
        "%Tolerance (SV/Toler)",
        "Number of Distinct Categories = 4",
    ] {
        assert!(text.contains(key), "missing {key}");
    }
    assert_eq!(r.charts().len(), 6);
    let titles: Vec<&str> = a.charts.iter().map(|c| c.title.as_str()).collect();
    assert_eq!(
        titles,
        vec![
            "Components of Variation",
            "R Chart by Operator",
            "Xbar Chart by Operator",
            "Measurements by Part",
            "Measurements by Operator",
            "Operator * Part Interaction"
        ]
    );
    // Components of variation: 3 series (with tolerance), 4 bars; limits present on the control charts.
    assert_eq!(a.charts[0].series.len(), 3);
    assert_eq!(a.charts[0].categories.len(), 4);
    assert_eq!(
        a.charts[1].series.iter().map(|s| s.name.as_str()).collect::<Vec<_>>(),
        vec!["Range", "UCL", "Center", "LCL"]
    );
    assert_eq!(a.charts[1].series[0].y.len(), 30);
    assert_eq!(a.charts[5].series.len(), 3);
    same_json(&s.xbar_r(&GageOptions::default()).unwrap().to_report("xbar-r"));
    let (y, op, part) = stacked_from_cells(GRN_Y, 3, 4, "O", "P");
    same_json(
        &NestedStudy::from_stacked(&y, &part, &op).unwrap().anova(&GageOptions::default()).unwrap().to_report("nested"),
    );
}

#[test]
fn anova_reports_render() {
    let a = ow();
    let r = a.to_report("One-way");
    same_json(&r);
    let t = r.render_text();
    for key in ["Analysis of Variance", "R-sq(pred)", "Welch's Test", "Pooled StDev"] {
        assert!(t.contains(key), "missing {key}");
    }
    assert_eq!(r.charts().len(), 2);
    for c in [
        a.tukey(0.05).unwrap().to_report("tukey"),
        a.fisher(0.05).unwrap().to_report("fisher"),
        a.dunnett(0, Alternative::TwoSided, 0.05).unwrap().to_report("dunnett"),
        a.dunnett(0, Alternative::Greater, 0.05).unwrap().to_report("dunnett one-sided"),
        a.hsu_mcb(Best::Smallest, 0.05).unwrap().to_report("mcb"),
        glm("y ~ A + B + x + A*B", &glm1(), &GlmOptions::default()).unwrap().to_report("glm"),
    ] {
        same_json(&c);
    }
    let tk = a.tukey(0.05).unwrap().to_report("t").render_text();
    assert!(
        tk.contains("Grouping Information")
            && tk.contains("Adjusted P-Value")
            && tk.contains("Individual confidence level")
    );
    let g = glm("y ~ A + B + x + A*B", &glm1(), &GlmOptions::default()).unwrap().to_report("g").render_text();
    assert!(g.contains("Type III") && g.contains("Sequential") && g.contains("Least Squares Means for A*B"));
}

#[test]
fn stacked_one_way_and_errors() {
    let values: Vec<f64> = OW_GROUPS.iter().flat_map(|g| g.iter().copied()).collect();
    let labels: Vec<String> =
        OW_GROUPS.iter().enumerate().flat_map(|(i, g)| std::iter::repeat_n(format!("L{}", i + 1), g.len())).collect();
    let s = one_way_stacked(&values, &labels, &OneWayOptions::default()).unwrap();
    close(s.f.unwrap(), OW_REF[3], 1e-11, "stacked F");
    assert!(one_way_stacked(&values, &labels[1..], &OneWayOptions::default()).is_err());
    assert!(one_way(OW_GROUPS, None, &OneWayOptions { level: 1.5 }).is_err());
    assert!(glm("y ~ A", &Data::new(), &GlmOptions::default()).is_err());
}
